def is_in_set(n, a, b):
    if n == 1:
        return True
    if n % a != 0 and n % b != 0:
        return False
    current = 1
    while current < n:
        if current * a > n:
            break
        current *= a
        if current == n:
            return True
    while current > 1:
        if (n - current) % b == 0:
            return True
        current //= a
    return False

def main():
    t = int(input())
    results = []
    for _ in range(t):
        n, a, b = map(int, input().split())
        if is_in_set(n, a, b):
            results.append('Yes')
        else:
            results.append('No')
    print('\n'.join(results))

